import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';
import Ajv, {type ErrorObject, type ValidateFunction} from 'ajv';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
  validators: WeakMap<object, ValidateFunction>;
}

const ajv = new Ajv({
  strict: false,
  validateFormats: false,
});

function invalidInput(name: string, errors: ErrorObject[]): ToolResponse {
  const message = errors.map(formatValidationError);
  log.warn('tool', 'input validation failed', {
    name,
    paths: errors.map(error => {
      const details = error as {params?: {missingProperty?: string}};
      return details.params?.missingProperty ?? inputErrorPath(error);
    }),
    keywords: errors.map(error => error.keyword),
  });
  return {result: `Tool '${name}' input invalid: ${message.join('; ')}`};
}

function formatValidationError(error: ErrorObject): string {
  const details = error as {
    keyword: string;
    params: {missingProperty?: string};
    message?: string;
  };
  return details.keyword === 'required'
    ? `${inputErrorPath(error, details.params.missingProperty)} is required`
    : `${inputErrorPath(error)} ${details.message ?? 'is invalid'} (${details.keyword})`;
}

function inputErrorPath(error: ErrorObject, missingProperty?: string): string {
  const details = error as {instancePath?: string; dataPath?: string};
  const path = details.instancePath || details.dataPath || '(root)';
  const normalizedPath = path.startsWith('.') ? `/${path.slice(1).replaceAll('.', '/')}` : path;
  if (!missingProperty) return normalizedPath;
  return normalizedPath === '(root)' ? `/${missingProperty}` : `${normalizedPath}/${missingProperty}`;
}

function malformedInput(name: string, input: unknown): TypeError {
  const kind = input === null ? 'null' : Array.isArray(input) ? 'array' : typeof input;
  return new TypeError(`Tool '${name}' needs an object as input, and got ${kind}`);
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Unable to compile input schema for tool '${resolved.name}': ${String(error)}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator, validators: new WeakMap()});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the registered schema; schema rejection returns a ToolResponse, unknown tools throw (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    if (input === null || typeof input !== 'object' || Array.isArray(input)) {
      throw malformedInput(name, input);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = typeof tool.definitionSource === 'function' ? tool.definitionSource() : undefined;
    const validator = tool.validator ?? this.getDynamicValidator(tool, definition);
    if (!validator(input)) {
      return invalidInput(name, validator.errors ?? []);
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private getDynamicValidator(tool: StoredTool, definition: ToolDefinition | undefined): ValidateFunction {
    if (!definition) throw new Error('Missing dynamic tool definition');
    const cached = tool.validators.get(definition.inputSchema);
    if (cached) return cached;
    try {
      const validator = ajv.compile(definition.inputSchema);
      tool.validators.set(definition.inputSchema, validator);
      return validator;
    } catch (error) {
      throw new Error(`Unable to compile input schema for tool '${definition.name}': ${String(error)}`, {cause: error});
    }
  }
}
import {ToolRegistry} from './registry.js';
import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {setLogger} from '../../shared/logger.js';

describe('ToolRegistry dynamic input validation', () => {
  // spec: specs/hal-engine-tool-input-validation#7
  it('validates each function-valued definition against its current schema', async () => {
    const registry = new ToolRegistry();
    let definitionCalls = 0;
    let executorCalls = 0;
    registry.register(
      () => {
        definitionCalls += 1;
        const required = definitionCalls === 2 ? 'location' : 'city';
        return {
          name: 'get_weather',
          description: 'Get weather for a location',
          inputSchema: {
            type: 'object',
            properties: {[required]: {type: 'string'}},
            required: [required],
          },
        };
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const firstResponse = await registry.execute('get_weather', {location: 'Paris'});
    const secondResponse = await registry.execute('get_weather', {location: 'Paris'});

    expect({
      definitionCalls,
      executorCalls,
      firstResult: firstResponse.result,
      secondResult: secondResponse.result,
    }).toEqual({
      definitionCalls: 3,
      executorCalls: 1,
      firstResult: 'sunny',
      secondResult: expect.stringContaining('city'),
    });
  });
});

describe('ToolRegistry required input validation', () => {
  // spec: specs/hal-engine-tool-input-validation#1
  it('returns a rejection for missing required input without invoking the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {});

    expect({result: response.result, executorCalls}).toEqual({
      result: expect.stringMatching(/location.*required/),
      executorCalls: 0,
    });
  });

  // spec: specs/hal-engine-tool-input-validation#1
  it('logs the missing required property path without input values', async () => {
    const warnings: Array<{fields?: Record<string, unknown>}> = [];
    setLogger({
      debug: () => undefined,
      info: () => undefined,
      warn: (_category, _message, fields) => warnings.push({fields}),
      error: () => undefined,
    });
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => 'sunny'
    );

    await registry.execute('weather', {});

    expect(warnings).toEqual([{fields: {name: 'weather', paths: ['location'], keywords: ['required']}}]);
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('names the complete path for a nested missing required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {
            request: {
              type: 'object',
              properties: {location: {type: 'string'}},
              required: ['location'],
            },
          },
          required: ['request'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {request: {}});

    expect(response.result).toEqual(expect.stringContaining('/request/location'));
  });
});

describe('ToolRegistry static schema compilation', () => {
  // spec: specs/hal-engine-tool-input-validation#6
  it('compiles a static schema once at registration across ten executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
      },
      async () => 'sunny'
    );

    for (let index = 0; index < 10; index += 1) {
      await registry.execute('weather', {location: 'Paris'});
    }

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });
});

describe('ToolRegistry validation diagnostics', () => {
  // spec: specs/hal-engine-tool-input-validation#3
  it('names the enum constraint when rejecting a disallowed value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}}},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {unit: 'kelvin'});

    expect({result: response.result, executorCalls}).toEqual({
      result: expect.stringMatching(/\/unit.*enum/),
      executorCalls: 0,
    });
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('logs a rejected field path and constraint without logging its value', async () => {
    const warnings: Array<{message: string; fields?: Record<string, unknown>}> = [];
    setLogger({
      debug: () => undefined,
      info: () => undefined,
      warn: (category, message, fields) => {
        if (category === 'tool') warnings.push({message, fields});
      },
      error: () => undefined,
    });
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'notify',
        description: 'send a notification',
        inputSchema: {type: 'object', properties: {email: {type: 'string'}}, required: ['email']},
      },
      async () => 'sent'
    );

    const response = await registry.execute('notify', {email: 42});

    expect({result: response.result, warnings, leakedValue: JSON.stringify(warnings).includes('42')}).toEqual({
      result: expect.stringMatching(/email.*string/),
      warnings: [
        {
          message: expect.stringMatching(/validation failed/),
          fields: {name: 'notify', paths: ['/email'], keywords: ['type']},
        },
      ],
      leakedValue: false,
    });
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('reports a root property path for a wrong-typed field', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'notify',
        description: 'send a notification',
        inputSchema: {type: 'object', properties: {email: {type: 'string'}}},
      },
      async () => 'sent'
    );

    const response = await registry.execute('notify', {email: 42});

    expect(response.result).toEqual(expect.stringMatching(/email.*string/));
  });
});

describe('ToolRegistry malformed input', () => {
  // spec: specs/hal-engine-tool-input-validation#4
  it('rejects non-object input with a TypeError naming the tool and value kind', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {type: 'object'},
      },
      async () => 'sunny'
    );

    await expect(registry.execute('weather', null as unknown as Record<string, unknown>)).rejects.toThrow(
      "Tool 'weather' needs an object as input, and got null"
    );
  });

  describe('ToolRegistry valid input pass-through', () => {
    // spec: specs/hal-engine-tool-input-validation#4
    it('passes valid input and undeclared properties to the executor unchanged exactly once', async () => {
      const registry = new ToolRegistry();
      const input = {location: 'Paris', callerName: 'Ada'};
      const executorInputs: Array<Record<string, unknown>> = [];
      registry.register(
        {
          name: 'weather',
          description: 'Get weather',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'string'}},
            required: ['location'],
          },
        },
        async receivedInput => {
          executorInputs.push(receivedInput);
          return 'sunny';
        }
      );

      await registry.execute('weather', input);

      expect({executorInputs, callCount: executorInputs.length}).toEqual({
        executorInputs: [input],
        callCount: 1,
      });
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required, including its complete nested path, and never invokes the executor ([validated by: returns a rejection for missing required input without invoking the executor](../../src/orchestration/tools/registry.test.ts#L51), [validated by: logs the missing required property path without input values](../../src/orchestration/tools/registry.test.ts#L75), [validated by: names the complete path for a nested missing required property](../../src/orchestration/tools/registry.test.ts#L99), [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [validated by: logs a rejected field path and constraint without logging its value](../../src/orchestration/tools/registry.test.ts#L151), [validated by: reports a root property path for a wrong-typed field](../../src/orchestration/tools/registry.test.ts#L186)).
- When `input` violates an `enum` constraint, the rejection names the failing field path and the `enum` constraint without invoking the executor ([validated by: names the enum constraint when rejecting a disallowed value](../../src/orchestration/tools/registry.test.ts#L151)).
- When `input` is not an object, `ToolRegistry.execute` rejects with a `TypeError` naming the tool and the input kind rather than validating it against the schema ([validated by: rejects non-object input with a TypeError naming the tool and value kind](../../src/orchestration/tools/registry.test.ts#L205)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input and undeclared properties to the executor unchanged exactly once](../../src/orchestration/tools/registry.test.ts#L223)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: compiles a static schema once at registration across ten executions](../../src/orchestration/tools/registry.test.ts#L128)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates each function-valued definition against its current schema](../../src/orchestration/tools/registry.test.ts#L8)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
